namespace duckdb_snappy {

void Bignum::Append32(std::string* s, uint32_t value) {
  char buf[Bignum::kMax32];
  const char* p = Bignum::Encode32(buf, value);
  s->append(buf, p - buf);
}

}  // namespace duckdb_snappy


